// Self-contained worker bundles, spawned from blob: URLs (design A39).
//
// The shipped dashboard is one HTML file whose CSP allows `worker-src 'self'
// blob:` and whose single-file law forbids separate worker files. These
// bundles let it run the wasi-threads pool and the FlatSQL I/O worker anyway:
//
//   import { hostWorkerBundleUrl } from "space-data-module-sdk/host/worker-bundles";
//   await createWasiThreadSpawn({ ..., poolSize,
//     browserWorkerUrl: hostWorkerBundleUrl("wasi-thread-pool"),
//     browserWorkerType: "classic" });
//   await createFlatsqlIoWorker({ ...,
//     workerUrl: hostWorkerBundleUrl("flatsql-io"), workerType: "classic" });
//
// The sources are generated by scripts/build-host-worker-bundles.mjs (esbuild
// IIFE of src/host/wasiThreadBrowserWorker.mjs and src/host/opfsIoWorker.mjs).
// `{ moduleUrl }` extraImports need a module worker; the bundles serve the
// built-in `{ provider: "flatsql-io" }` descriptor.

import {
  FLATSQL_IO_WORKER_BUNDLE,
  FLATSQL_IO_WORKER_BUNDLE_SHA256,
  WASI_THREAD_POOL_WORKER_BUNDLE,
  WASI_THREAD_POOL_WORKER_BUNDLE_SHA256,
} from "./hostWorkerBundleSources.js";

export const HOST_WORKER_BUNDLES = Object.freeze({
  "wasi-thread-pool": Object.freeze({
    source: WASI_THREAD_POOL_WORKER_BUNDLE,
    sha256: WASI_THREAD_POOL_WORKER_BUNDLE_SHA256,
  }),
  "flatsql-io": Object.freeze({
    source: FLATSQL_IO_WORKER_BUNDLE,
    sha256: FLATSQL_IO_WORKER_BUNDLE_SHA256,
  }),
});

const urls = new Map();

function bundleFor(kind) {
  const bundle = HOST_WORKER_BUNDLES[kind];
  if (!bundle) {
    throw new RangeError(
      `Unknown host worker bundle "${kind}"; expected one of ${Object.keys(HOST_WORKER_BUNDLES).join(", ")}.`,
    );
  }
  return bundle;
}

/** The classic-script source of a bundle. */
export function hostWorkerBundleSource(kind) {
  return bundleFor(kind).source;
}

/**
 * A blob: URL for a bundle (created once per kind and reused). Spawn it as a
 * CLASSIC worker: `new Worker(url)`, or pass `browserWorkerType: "classic"` /
 * `workerType: "classic"` to the SDK hosts.
 */
export function hostWorkerBundleUrl(kind) {
  const bundle = bundleFor(kind);
  let url = urls.get(kind);
  if (!url) {
    url = URL.createObjectURL(new Blob([bundle.source], { type: "text/javascript" }));
    urls.set(kind, url);
  }
  return url;
}

/** Revoke the blob URLs created by hostWorkerBundleUrl. */
export function revokeHostWorkerBundleUrls() {
  for (const url of urls.values()) {
    try {
      URL.revokeObjectURL(url);
    } catch {
      // ignore
    }
  }
  urls.clear();
}
